  "mobile.about.disclaimer": "Quit Journey ನಿಮ್ಮ ಚೇತರಿಕೆಗೆ ಬೆಂಬಲ ನೀಡುತ್ತದೆ; ಇದು ವೈದ್ಯಕೀಯ ಸಲಹೆ ಅಥವಾ ಚಿಕಿತ್ಸೆ ಅಲ್ಲ. ಚೇತರಿಕೆಯ ಸಮಯರೇಖೆಗಳು ಸಾರ್ವಜನಿಕ ಆರೋಗ್ಯ ಮಾರ್ಗದರ್ಶನವನ್ನು (WHO, CDC, NHS, NIAAA, NIDA, SAMHSA) ಮತ್ತು ಪ್ರತಿ ಸಮಯರೇಖೆಯಲ್ಲಿ ಹೆಸರಿಸಿದ ಅಧ್ಯಯನಗಳನ್ನು ಸಂಕ್ಷೇಪಿಸುತ್ತವೆ.",
