  "safety.timer.intro": "ನೀವು ಬಳಸುವುದಾದರೆ, ಒಂಟಿಯಾಗಿ ಬಳಸಬೇಡಿ. ಟೈಮರ್ ಶುರು ಮಾಡಿ: ಸಮಯಕ್ಕೆ ಸರಿಯಾಗಿ “ನಾನು ಚೆನ್ನಾಗಿದ್ದೇನೆ” ಒತ್ತದಿದ್ದರೆ, ಹತ್ತಿರದಲ್ಲಿರುವ ಯಾರಾದರೂ ಸಹಾಯ ಮಾಡಲು ನಿಮ್ಮ ಫೋನ್ ಜೋರಾಗಿ ಅಲಾರಂ ಮೊಳಗಿಸುತ್ತದೆ, ಮತ್ತು ನೀವು ಒಂದೇ ಟ್ಯಾಪ್‌ನಲ್ಲಿ ನಿಮ್ಮ ಸಂಪರ್ಕಕ್ಕೆ ಸಂದೇಶ ಕಳುಹಿಸಬಹುದು. ಆ್ಯಪ್ ತಾನಾಗಿಯೇ ಯಾರಿಗೂ ಕರೆ ಮಾಡಲು ಸಾಧ್ಯವಿಲ್ಲ.",
  "safety.timer.lateWarning": "ನಿಮ್ಮ ಫೋನ್ ಈ ಅಲಾರಂ ಅನ್ನು ಕೆಲವು ನಿಮಿಷ ತಡವಾಗಿ ಮೊಳಗಿಸಬಹುದು. ಸಮಯಕ್ಕೆ ಸರಿಯಾಗಿ ಮೊಳಗಲು Android ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಈ ಆ್ಯಪ್‌ಗೆ “ಅಲಾರಂಗಳು ಮತ್ತು ಜ್ಞಾಪನೆಗಳು” ಅನುಮತಿಸಿ.",
